// Data of the «Consolas» views, generated by contenido/consolas.py into public/consolas/ (see ESQUEMA.md).

export type IdMaquina = 'nes' | 'neogeo';

export interface Hotspot {
  id: string;
  nombre: string;
  pieza: string;
  esquema: string[];
  bloque: string;
  /** Boxes in photo pixels [x0, y0, x1, y1]. */
  cajas: [number, number, number, number][];
  confianza: 'marca' | 'posicion';
  buses: string[];
  funcion: string;
  /** What was checked against SNK documents, with page citations (Neo Geo). */
  verificacion?: string;
}

export interface Hoja {
  id: number;
  nombre: string;
  ruta: string;
  archivo: string;
  ancho: number;
  alto: number;
  padre: number | null;
}

export interface Componente {
  v: string;
  l: string;
  h: number[];
  f?: string;
}

export interface Red {
  n: string;
  g: string | null;
  nodos: [string, string, string][];
  h: number[];
}

export interface Equivalencia {
  foto: string;
  esquema: string;
  senales?: string;
  cambios?: string;
  /** Page citations (MV4 h.N, AES h.N, MV4F h.N, NG Hw-N). */
  fuente?: string;
  nota?: string;
}

export interface Fuente {
  titulo: string;
  autor: string;
  url: string;
  licencia: string;
  uso: string;
}

export interface DatosMaquina {
  version: number;
  id: IdMaquina;
  titulo: string;
  placa: string;
  esquema_titulo: string;
  aviso: string;
  foto: { src: string; ancho: number; alto: number; figura: string };
  hotspots: Hotspot[];
  grupos: Record<string, string>;
  hojas: Hoja[];
  componentes: Record<string, Componente>;
  redes: Red[];
  equivalencias: Equivalencia[];
  fuentes: Fuente[];
}

/** Electrical layer of a sheet; coordinates in 0.01 mm. */
export interface CapaHoja {
  w: number;
  h: number;
  /** [net, x1, y1, x2, y2] repeated. */
  hilos: number[];
  /** [net, x, y] repeated. */
  uniones: number[];
  /** net, ref, pin number, pin name, connection point, inner end. */
  pines: [number, string, string, string, number, number, number, number][];
  /** net (−1 for bus labels), kind (local, global, hier, pwr, bus), text, box. */
  etiquetas: [number, string, string, number, number, number, number][];
  simbolos: [string, number, number, number, number][];
  /** [x1, y1, x2, y2] repeated. */
  buses: number[];
  subhojas: [number, string, number, number, number, number, [number, string, number, number][]][];
}

const cache = new Map<string, Promise<unknown>>();

function pedir<T>(ruta: string, binario = false): Promise<T> {
  let p = cache.get(ruta);
  if (!p) {
    p = fetch(ruta).then((r) => {
      if (!r.ok) throw new Error(`No se pudo cargar ${ruta} (${r.status})`);
      return binario ? r.arrayBuffer() : r.json();
    });
    p.catch(() => cache.delete(ruta));
    cache.set(ruta, p);
  }
  return p as Promise<T>;
}

export function cargarMaquina(id: IdMaquina): Promise<DatosMaquina> {
  return pedir<DatosMaquina>(`consolas/${id}.json`);
}

export function cargarCapa(h: Hoja): Promise<CapaHoja> {
  return pedir<CapaHoja>(`consolas/${h.archivo}.json`);
}

export function cargarDibujo(h: Hoja): Promise<ArrayBuffer> {
  return pedir<ArrayBuffer>(`consolas/${h.archivo}.bin`, true);
}

// ------------------------------------------------------------------ names

/** KiCad text markup: «~{NMI}» is an overbar, «{slash}» a slash. */
export function textoKicad(s: string): string {
  return s.replace(/\{slash\}/g, '/').replace(/~\{([^}]*)\}/g, '/$1');
}

/** Net name for display: «/CPU/A1» → «A1», with the sheet in `hoja`. */
export function nombreRed(n: string): { nombre: string; hoja: string | null } {
  const limpio = textoKicad(n);
  const m = /^\/(.+)\/([^/]+)$/.exec(n);
  if (m) return { nombre: textoKicad(m[2]!), hoja: m[1]! };
  return { nombre: limpio.replace(/^\//, ''), hoja: null };
}

/** HTML of a KiCad name with real overbars. */
export function htmlKicad(s: string): string {
  const esc = (t: string) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return esc(s.replace(/\{slash\}/g, '/')).replace(/~\{([^}]*)\}/g, '<span class="sobre">$1</span>');
}

export function normalizar(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/~\{([^}]*)\}/g, '$1')
    .toLowerCase();
}
